/* ===================================================================
 * WINX ELEMENT SEED — shared family model (voxel.exec source)
 * Only the ELEMENT block below changes between elements; everything
 * under "FAMILY" is identical for all 9 seeds so the icons match.
 * STAGE 3 (final form): same egg + snowflake, stage-2 cradle, plus large
 * ice-crystal wings (big shard fans, white/blue facets, glowing cores) swept
 * up and back to frame the egg, and a tall crystalline crown with glowstone.
 * =================================================================== */

/* ---------------- ELEMENT (per-element config) ---------------- */
const EL = {
  name: 'ice',
  lower: 'white_wool',     // crystal colour, bottom half: packed snow
  upper: 'blue_wool',      // crystal colour, top half: icy blue behind the snowflake
  core: 'white_wool',      // emblem front: bright frost white
  rim: 'blue_wool',        // emblem back/side layers
  // Emblem: bold 6-armed snowflake. u = blocks right of the egg axis
  // (screen-right), y = world height, E = egg params. Strokes >= 3 blocks.
  emblem: function (u, y, E) {
    const cv = 0.60;                      // centre height (fraction of egg)
    const px = u, py = y - (E.y0 + cv * E.h);
    const r = Math.hypot(px, py);
    if (r <= HUB) return true;            // solid hub
    for (let k = 0; k < 6; k++) {
      const a = Math.PI / 2 + k * Math.PI / 3; // one arm straight up
      const dx = Math.cos(a), dy = Math.sin(a);
      const t = px * dx + py * dy, n = Math.abs(-px * dy + py * dx);
      if (t > 0 && t <= ARM && n <= HW) return true;          // arm shaft
      const ex = px - dx * ARM, ey = py - dy * ARM;
      if (ex * ex + ey * ey <= TIP * TIP) return true;         // rounded ice-crystal tip
    }
    return false;
  },
};
const HUB = 2.4, ARM = 9.2, HW = 1.55, TIP = 2.1; // hub radius, arm length, stroke half-width, tip radius (blocks)

/* ---------------- FAMILY (shared, do not edit per element) ---------------- */
const CX = 128, CZ = 128;
const VIEW = 30 * Math.PI / 180;  // MUST equal CAMERA_YAW in render_icon.js: emblem faces the icon camera
const E = { y0: 6, h: 46, R: 15 }; // egg: bottom y, height, max apothem
// faceted profile: piecewise-linear apothem (fraction of R) at knots of v
const KN = [[0, 0.0], [0.03, 0.42], [0.10, 0.74], [0.20, 0.94], [0.32, 1.0], [0.46, 0.95], [0.60, 0.80], [0.74, 0.58], [0.87, 0.33], [0.96, 0.12], [1.0, 0.0]];
function prof(y) {
  const v = (y - E.y0) / E.h;
  if (v < 0 || v > 1) return -1;
  for (let i = 1; i < KN.length; i++) if (v <= KN[i][0]) {
    const f = (v - KN[i - 1][0]) / (KN[i][0] - KN[i - 1][0]);
    return E.R * (KN[i - 1][1] + f * (KN[i][1] - KN[i - 1][1]));
  }
  return 0;
}
// octagonal cross-section (8 facets), one flat facet facing the camera
function octd(dx, dz) {
  let m = 0;
  for (let k = 0; k < 4; k++) {
    const th = VIEW + k * Math.PI / 4;
    m = Math.max(m, Math.abs(dx * Math.sin(th) - dz * Math.cos(th)));
  }
  return m;
}
function inEgg(x, y, z) { const r = prof(y); return r > 0 && octd(x - CX, z - CZ) <= r + 0.35; }
// surface radius along azimuth phi (phi=0 -> towards the camera)
function surfR(y, phi) {
  const dx = Math.sin(VIEW + phi), dz = -Math.cos(VIEW + phi);
  return Math.max(0, prof(y)) / octd(dx, dz);
}
function azPt(phi, rho, y) { return [CX + Math.sin(VIEW + phi) * rho, y, CZ - Math.cos(VIEW + phi) * rho]; }

// ---- 1. crystal body: glass skin, colour-blended interior, emblem core
const Y0 = E.y0, Y1 = E.y0 + E.h;
const EMB_W0 = -3, EMB_W1 = 1, WALL_W = 2, SOLID_V = 0.33; // emblem slab depth range, back wall start; below SOLID_V (inside the cup) the core is solid
for (let y = Y0; y <= Y1; y++) for (let x = CX - E.R - 2; x <= CX + E.R + 2; x++) for (let z = CZ - E.R - 2; z <= CZ + E.R + 2; z++) {
  if (!inEgg(x, y, z)) continue;
  const skin = !(inEgg(x + 1, y, z) && inEgg(x - 1, y, z) && inEgg(x, y + 1, z) && inEgg(x, y - 1, z) && inEgg(x, y, z + 1) && inEgg(x, y, z - 1));
  const u = (x - CX) * Math.cos(VIEW) + (z - CZ) * Math.sin(VIEW);
  const v = (y - Y0) / E.h;
  if (skin) { block(x, y, z, 'glass'); continue; }
  // w: depth along the camera's horizontal view direction (negative = towards camera)
  const w = -(x - CX) * Math.sin(VIEW) + (z - CZ) * Math.cos(VIEW);
  if (w < EMB_W0 && v > SOLID_V) continue;                   // hollow front: you look through glass into the core
  if (w <= EMB_W1 && EL.emblem(u, y, E)) { block(x, y, z, w < EMB_W0 + 1.5 ? EL.core : EL.rim); continue; }
  if (w < WALL_W && v > SOLID_V) continue;                                  // gap so the emblem floats in front of the back wall
  // back wall: lower colour -> dithered band -> upper colour
  const band = 0.30 + 0.015 * Math.sin(Math.atan2(z - CZ, x - CX) * 4);
  let m;
  if (v < band - 0.04) m = EL.lower; else if (v > band + 0.04) m = EL.upper;
  else m = ((x + y + z) & 1) ? EL.lower : EL.upper;
  block(x, y, z, m);
}

// ---- helpers for the gold filigree (swept spheres)
function ball(cx, cy, cz, r, m) {
  for (let x = Math.floor(cx - r); x <= Math.ceil(cx + r); x++)
    for (let y = Math.floor(cy - r); y <= Math.ceil(cy + r); y++)
      for (let z = Math.floor(cz - r); z <= Math.ceil(cz + r); z++)
        if ((x - cx) ** 2 + (y - cy) ** 2 + (z - cz) ** 2 <= r * r) block(x, y, z, m);
}
function sweep(pts, r0, r1, m) {
  let L = 0; const seg = [];
  for (let i = 1; i < pts.length; i++) { const d = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1], pts[i][2] - pts[i - 1][2]); seg.push(d); L += d; }
  let acc = 0;
  for (let i = 1; i < pts.length; i++) {
    const n = Math.max(1, Math.ceil(seg[i - 1] * 3));
    for (let j = 0; j <= n; j++) {
      const t = j / n, s = (acc + seg[i - 1] * t) / (L || 1);
      ball(pts[i - 1][0] + (pts[i][0] - pts[i - 1][0]) * t, pts[i - 1][1] + (pts[i][1] - pts[i - 1][1]) * t, pts[i - 1][2] + (pts[i][2] - pts[i - 1][2]) * t, r0 + (r1 - r0) * s, m);
    }
    acc += seg[i - 1];
  }
}
const G = 'gold_block';

// ---- 2. foot: stepped octagonal pedestal (touches Y=0) + neck knot
for (let y = 0; y <= 4; y++) {
  const r = [6.4, 6.4, 4.6, 3.2, 3.6][y];
  for (let x = CX - 8; x <= CX + 8; x++) for (let z = CZ - 8; z <= CZ + 8; z++)
    if (octd(x - CX, z - CZ) <= r) block(x, y, z, G);
}
for (let x = CX - 5; x <= CX + 5; x++) for (let z = CZ - 5; z <= CZ + 5; z++)
  if (octd(x - CX, z - CZ) <= 1.6) block(x, 1, z, 'glowstone'); // hidden jewel seat (keeps foot solid)
[0, 1, 2, 3].forEach(k => { const p = azPt(k * Math.PI / 2 + Math.PI / 4, 6.2, 1.2); ball(p[0], p[1], p[2], 1.3, 'glowstone'); }); // 4 foot jewels

// ---- 3. cradle ribs with clef-like volutes
// 3 ribs: two at the silhouette sides (+-90deg from camera) with big clef curls,
// one at the back with a small curl; nothing crosses the emblem window at the front.
const RIB_TOP = 0.34; // ribs hug the egg up to here, then curl outward
function rib(phi, s0, turns) {
  const pts = [];
  for (let v = 0.0; v <= RIB_TOP + 1e-6; v += 0.02) {
    const y = Y0 + v * E.h - 1.2;
    pts.push(azPt(phi, Math.max(3.2, surfR(y + 1.2, phi) + 0.9), y));
  }
  // volute: spiral in the (radial, y) plane, starting upward, curling outward & down
  const last = pts[pts.length - 1];
  const rho0 = Math.hypot(last[0] - CX, last[2] - CZ), yc = last[1];
  const cr = rho0 + s0;
  for (let th = Math.PI; th >= Math.PI - turns * 2 * Math.PI; th -= 0.08) {
    const f = (Math.PI - th) / (turns * 2 * Math.PI);
    const rad = s0 * (1 - 0.62 * f);
    pts.push(azPt(phi, cr + rad * Math.cos(th), yc + rad * Math.sin(th) * 1.15));
  }
  sweep(pts, 1.55, 0.95, G);
  // bead where the rib leaves the egg
  ball(last[0], last[1], last[2], 1.9, G);
}
rib(Math.PI / 2, 5.2, 1.05);
rib(-Math.PI / 2, 5.2, 1.05);
rib(Math.PI, 2.6, 0.8);

// ---- 4. rings: girdle at the top of the cup + a low collar
function ring(v, off, r, m) {
  const pts = [];
  const y = Y0 + v * E.h;
  for (let a = 0; a <= 2 * Math.PI + 0.05; a += 0.05) pts.push(azPt(a, surfR(y, a) + off, y));
  sweep(pts, r, r, m);
}
ring(RIB_TOP - 0.02, 0.6, 1.25, G);
ring(0.08, 0.5, 1.15, G);

// ---- 5. side cage arcs: from the side volutes up to the crown (never cross the emblem)
function arc(phi) {
  const pts = [];
  for (let v = RIB_TOP + 0.04; v <= 0.95; v += 0.015) {
    const y = Y0 + v * E.h;
    pts.push(azPt(phi, surfR(y, phi) + 0.7, y));
  }
  sweep(pts, 1.05, 0.9, G);
}
arc(Math.PI / 2); arc(-Math.PI / 2); arc(Math.PI);

// ---- 5b. wings (stage-2 shard helper kept; stage 3 uses crystal() below): clusters of angular ice-crystal shards (faceted
// bipyramids: glass skin over a white/iron core) sweeping up and back from
// the egg's sides, rooted in a gold socket behind the side cage arc.
function shard(b, d, len, rad, core, skinM) {
  skinM = skinM || 'glass';
  const L = Math.hypot(d[0], d[1], d[2]); const a = [d[0] / L, d[1] / L, d[2] / L];
  // perpendicular frame
  let p = Math.abs(a[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0];
  let e1 = [a[1] * p[2] - a[2] * p[1], a[2] * p[0] - a[0] * p[2], a[0] * p[1] - a[1] * p[0]];
  const l1 = Math.hypot(e1[0], e1[1], e1[2]); e1 = e1.map(q => q / l1);
  const e2 = [a[1] * e1[2] - a[2] * e1[1], a[2] * e1[0] - a[0] * e1[2], a[0] * e1[1] - a[1] * e1[0]];
  let lastUp = 0, lastT = 0;
  const inside = (x, y, z) => {
    const q = [x - b[0], y - b[1], z - b[2]];
    const t = (q[0] * a[0] + q[1] * a[1] + q[2] * a[2]) / len;
    if (t < 0 || t > 1) return -1;
    const r = rad * (t < 0.22 ? 0.55 + 0.45 * t / 0.22 : Math.pow((1 - t) / 0.78, 0.9));
    const u = q[0] * e1[0] + q[1] * e1[1] + q[2] * e1[2], w = q[0] * e2[0] + q[1] * e2[1] + q[2] * e2[2];
    const hx = Math.max(Math.abs(u), Math.abs(w), (Math.abs(u) + Math.abs(w)) * 0.7071); // octagonal facets
    if (hx > r + 0.3) return -1;
    lastUp = u * e1[1] + w * e2[1]; lastT = t; return r - hx;
  };
  const tip = [b[0] + a[0] * len, b[1] + a[1] * len, b[2] + a[2] * len];
  const lo = [0, 1, 2].map(k => Math.floor(Math.min(b[k], tip[k]) - rad - 1)), hi = [0, 1, 2].map(k => Math.ceil(Math.max(b[k], tip[k]) + rad + 1));
  for (let x = lo[0]; x <= hi[0]; x++) for (let y = Math.max(0, lo[1]); y <= hi[1]; y++) for (let z = lo[2]; z <= hi[2]; z++) {
    const dd = inside(x, y, z); if (dd < 0) continue;
    block(x, y, z, lastT > 0.94 ? 'glass' : dd < 0.7 ? (lastUp > 0.3 ? core : skinM) : core);
  }
}
function dirAt(phi, elev) { // unit vector: radial at azimuth phi, tilted up by elev
  const c = Math.cos(elev);
  return [Math.sin(VIEW + phi) * c, Math.sin(elev), -Math.cos(VIEW + phi) * c];
}
// STAGE 3 crystal: faceted shard with white top facets, blue_wool under/side
// facets, a glowing glowstone core showing through a glass window near the
// base, and a clear glass tip.
function crystal(b, d, len, rad, sideM, glowTo) {
  const L = Math.hypot(d[0], d[1], d[2]); const a = [d[0] / L, d[1] / L, d[2] / L];
  let p = Math.abs(a[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0];
  let e1 = [a[1] * p[2] - a[2] * p[1], a[2] * p[0] - a[0] * p[2], a[0] * p[1] - a[1] * p[0]];
  const l1 = Math.hypot(e1[0], e1[1], e1[2]); e1 = e1.map(q => q / l1);
  const e2 = [a[1] * e1[2] - a[2] * e1[1], a[2] * e1[0] - a[0] * e1[2], a[0] * e1[1] - a[1] * e1[0]];
  const tip = [b[0] + a[0] * len, b[1] + a[1] * len, b[2] + a[2] * len];
  const lo = [0, 1, 2].map(k => Math.floor(Math.min(b[k], tip[k]) - rad - 1)), hi = [0, 1, 2].map(k => Math.ceil(Math.max(b[k], tip[k]) + rad + 1));
  for (let x = lo[0]; x <= hi[0]; x++) for (let y = Math.max(0, lo[1]); y <= hi[1]; y++) for (let z = lo[2]; z <= hi[2]; z++) {
    const q = [x - b[0], y - b[1], z - b[2]];
    const t = (q[0] * a[0] + q[1] * a[1] + q[2] * a[2]) / len;
    if (t < 0 || t > 1) continue;
    const r = rad * (t < 0.2 ? 0.6 + 0.4 * t / 0.2 : Math.pow((1 - t) / 0.8, 0.85));
    const u = q[0] * e1[0] + q[1] * e1[1] + q[2] * e1[2], w = q[0] * e2[0] + q[1] * e2[1] + q[2] * e2[2];
    const hx = Math.max(Math.abs(u), Math.abs(w), (Math.abs(u) + Math.abs(w)) * 0.7071);
    if (hx > r + 0.3) continue;
    const dd = r - hx, up = (u * e1[1] + w * e2[1]) / (Math.hypot(u, w) || 1);
    let m;
    if (t > 0.9) m = 'glass';
    else if (dd >= 0.7) m = t < glowTo ? 'glowstone' : 'white_wool';      // core
    else if (t < glowTo && t > 0.08) m = 'glass';                          // window onto the glowing core
    else {
      const nl = Math.hypot(u, w) || 1, nx = (u * e1[0] + w * e2[0]) / nl, nz = (u * e1[2] + w * e2[2]) / nl;
      const sr = nx * Math.cos(VIEW) + nz * Math.sin(VIEW);           // facet facing screen-right (shaded side)
      m = up > 0.4 ? 'white_wool' : (up < -0.4 || sr > 0.45) ? 'blue_wool' : sideM;
    }
    block(x, y, z, m);
  }
}
for (const sg of [1, -1]) {
  const phi = sg * Math.PI / 2;
  const vR = 0.50, yR = Y0 + vR * E.h;
  const root = azPt(phi + sg * 0.15, surfR(yR, phi) + 0.5, yR);
  const SW = sg * 0.12; // swept back so the egg stays large
  // [elevation deg, length, radius, azimuth extra, root dy, side material, glow extent]
  const S = [
    [58, 37, 4.8, 0.00, 2, 'white_wool', 0.30],
    [40, 28, 4.0, 0.10, 0, 'iron_block', 0.30],
    [76, 27, 3.6, -0.06, 5, 'iron_block', 0.28],
    [16, 20, 3.4, 0.18, -3, 'white_wool', 0.28],
    [-16, 10, 2.6, 0.20, -6, 'iron_block', 0.0],
    [48, 16, 2.8, 0.50, 3, 'white_wool', 0.0],
  ];
  for (const [el, len, rad, dp, dy, sm, gl] of S)
    crystal([root[0], root[1] + dy, root[2]], dirAt(phi + SW + sg * dp, el * Math.PI / 180), len, rad, sm, gl);
  ball(root[0], root[1], root[2], 2.8, G);               // gold socket
  const j = azPt(phi, surfR(yR, phi) + 2.0, yR); ball(j[0], j[1], j[2], 1.6, 'glowstone');
}

// ---- 6. crown (STAGE 2 base, STAGE 3 spires below): fuller gold cap, 8 leaves, a ring of icicle spikes
// and a tall central ice crystal with a glowing gem at its base.
const CAP_V = 0.88;
for (let y = Math.round(Y0 + CAP_V * E.h); y <= Y1 + 1; y++) for (let x = CX - 8; x <= CX + 8; x++) for (let z = CZ - 8; z <= CZ + 8; z++)
  if (octd(x - CX, z - CZ) <= Math.max(0, prof(y)) + 1.2 && (y - Y0) / E.h >= CAP_V) block(x, y, z, G);
ring(CAP_V, 1.0, 1.15, G);
for (let k = 0; k < 8; k++) {
  const phi = k * Math.PI / 4 + Math.PI / 8;
  const L = Math.cos(phi) > 0.5 ? 0.04 : 0.10;
  const pts = [];
  for (let t = 0; t <= 1.0001; t += 0.1) {
    const y = Y0 + (CAP_V - L * t) * E.h;
    pts.push(azPt(phi, surfR(y, phi) + 0.6 + 1.3 * Math.sin(t * Math.PI), y));
  }
  sweep(pts, 1.1, 0.6, G);
}
// STAGE 3 tall crystalline crown: longer icicles fanning out, glowing cores,
// and a tall central spire with a big glowing heart.
for (let k = 0; k < 6; k++) {
  const phi = k * Math.PI / 3 + Math.PI / 6;
  const side = Math.abs(Math.sin(phi));
  const yb = Y0 + (CAP_V + 0.02) * E.h;
  const b = azPt(phi, surfR(yb, phi) + 0.3, yb);
  crystal(b, dirAt(phi, (48 + 14 * (1 - side)) * Math.PI / 180), 11 + 4 * side, 2.6, 'iron_block', 0.3);
}
crystal([CX, Y1 - 2, CZ], [0, 1, 0], 22, 3.8, 'iron_block', 0.4);   // tall central crystal spire
ball(CX, Y1 + 0.5, CZ, 2.4, G);
